import { Component } from '@angular/core';
import { RouterLink } from '@angular/router';

@Component({
  selector: 'app-terms',
  standalone: true,
  imports: [RouterLink],
  template: `
    <div class="legal-page">
      <div class="legal-card">
        <a routerLink="/signup" class="legal-back">← Back</a>
        <h1>Terms of Service</h1>
        <p class="legal-updated">Last updated: August 2026</p>

        <h2>1. Acceptance of Terms</h2>
        <p>By creating an account or using EOS Fitness &amp; Pilates services, you agree to these Terms of Service.</p>

        <h2>2. Membership</h2>
        <p>Memberships are billed on a recurring basis unless cancelled. You may cancel anytime from your account settings; access continues until the end of the current billing period.</p>

        <h2>3. Class Bookings</h2>
        <p>Class spots are reserved on a first-come basis. Cancel at least 4 hours before a class to avoid a no-show fee.</p>

        <h2>4. Facility Use</h2>
        <p>Members are expected to follow gym etiquette and staff instructions. EOS reserves the right to suspend accounts for abusive behavior toward staff or other members.</p>

        <h2>5. Liability</h2>
        <p>You participate in physical training at your own risk. Consult a physician before beginning any new exercise program.</p>

        <h2>6. Changes</h2>
        <p>We may update these terms periodically. Continued use of the service after changes constitutes acceptance.</p>
      </div>
    </div>
  `,
  styles: [`
    .legal-page { min-height:100vh; background:var(--bg); color:var(--white); display:flex; justify-content:center; padding:60px 20px; font-family:'Poppins',sans-serif; }
    .legal-card { max-width:680px; width:100%; }
    .legal-back { color:var(--gray); text-decoration:none; font-size:14px; }
    h1 { margin:16px 0 4px; font-size:32px; }
    .legal-updated { color:var(--gray-dim); font-size:13px; margin-bottom:28px; }
    h2 { color:var(--gold-light); font-size:16px; margin:24px 0 8px; }
    p { color:var(--gray); line-height:1.6; font-size:14.5px; }
  `]
})
export class TermsComponent {}
